arguments.query:
WITH winword_children AS (
  SELECT pid FROM audit_logs WHERE pname = 'winword.exe'
), grandchildren AS (
  SELECT a.pid, a.ppid, a.process_name, a.command_line, a.time
  FROM audit_logs a
  JOIN winword_children wc ON a.ppid = wc.pid
)
SELECT pid, ppid, process_name, command_line, time FROM grandchildren;

